/**
 * 등불 거울 정원 (Lantern Mirror Garden) — an OIYO original light-beam puzzle.
 * Tap the bronze mirrors to turn them. Guide the amber and blue lights so every lantern
 * of the same colour glows, while the night flowers stay in the dark.
 * 30 stages, pre-generated by a seeded search; tests re-check every solution and par.
 *
 * Tiles: `.` empty, `#` wall, `m` turnable mirror "/", `n` turnable mirror "\",
 * `f` fixed "/", `g` fixed "\", `s` half-mirror "/", `t` half-mirror "\",
 * `>` `<` `^` `v` amber lights, `R` `L` `U` `D` blue lights,
 * `a` amber lantern, `b` blue lantern, `x` night flower (must stay dark).
 */

export const MIRROR_SLUG = "mirror-lanterns";

export type Dir = 0 | 1 | 2 | 3; // right, down, left, up
export type Color = "amber" | "blue";
export const DX = [1, 0, -1, 0] as const;
export const DY = [0, 1, 0, -1] as const;

export interface Level {
  rows: readonly string[];
  par: number;
}

export interface Board {
  w: number;
  h: number;
  tiles: string[][];
  /** positions of turnable mirrors, in reading order */
  mirrors: Array<[number, number]>;
}

const SOURCES: Record<string, { dir: Dir; color: Color }> = {
  ">": { dir: 0, color: "amber" }, v: { dir: 1, color: "amber" }, "<": { dir: 2, color: "amber" }, "^": { dir: 3, color: "amber" },
  R: { dir: 0, color: "blue" }, D: { dir: 1, color: "blue" }, L: { dir: 2, color: "blue" }, U: { dir: 3, color: "blue" },
};

export function sourceOf(t: string): { dir: Dir; color: Color } | undefined {
  return SOURCES[t];
}

export function parse(level: Level): Board {
  const tiles = level.rows.map((r) => [...r]);
  const mirrors: Array<[number, number]> = [];
  tiles.forEach((row, y) => row.forEach((t, x) => { if (t === "m" || t === "n") mirrors.push([x, y]); }));
  return { w: tiles[0].length, h: tiles.length, tiles, mirrors };
}

/** "/" turns right→up, up→right, left→down, down→left. */
function slash(d: Dir): Dir {
  return ([3, 2, 1, 0] as const)[d];
}
/** "\" turns right→down, down→right, left→up, up→left. */
function backslash(d: Dir): Dir {
  return ([1, 0, 3, 2] as const)[d];
}

export interface Segment {
  x: number;
  y: number;
  dir: Dir;
  color: Color;
}

export interface Trace {
  segments: Segment[];
  lit: Record<Color, Set<string>>;
}

/** Follows every beam from every light. Each segment is one beam entering a cell. */
export function trace(b: Board): Trace {
  const lit: Record<Color, Set<string>> = { amber: new Set(), blue: new Set() };
  const segments: Segment[] = [];
  const seen = new Set<string>();
  const queue: Segment[] = [];
  b.tiles.forEach((row, y) => row.forEach((t, x) => {
    const s = SOURCES[t];
    if (s) queue.push({ x: x + DX[s.dir], y: y + DY[s.dir], dir: s.dir, color: s.color });
  }));
  while (queue.length) {
    const seg = queue.shift()!;
    const { x, y, dir, color } = seg;
    if (x < 0 || y < 0 || x >= b.w || y >= b.h) continue;
    const k = `${x},${y},${dir},${color}`;
    if (seen.has(k)) continue;
    seen.add(k);
    const t = b.tiles[y][x];
    if (t === "#" || SOURCES[t]) continue;
    segments.push(seg);
    lit[color].add(`${x},${y}`);
    const go = (d: Dir) => queue.push({ x: x + DX[d], y: y + DY[d], dir: d, color });
    if (t === "m" || t === "f") go(slash(dir));
    else if (t === "n" || t === "g") go(backslash(dir));
    else if (t === "s") { go(dir); go(slash(dir)); }
    else if (t === "t") { go(dir); go(backslash(dir)); }
    else go(dir);
  }
  return { segments, lit };
}

export interface Goal {
  lanterns: number;
  litLanterns: number;
  flowersLit: number;
}

export function goal(b: Board, tr: Trace = trace(b)): Goal {
  let lanterns = 0;
  let litLanterns = 0;
  let flowersLit = 0;
  b.tiles.forEach((row, y) => row.forEach((t, x) => {
    const k = `${x},${y}`;
    if (t === "a") { lanterns += 1; if (tr.lit.amber.has(k)) litLanterns += 1; }
    if (t === "b") { lanterns += 1; if (tr.lit.blue.has(k)) litLanterns += 1; }
    if (t === "x" && (tr.lit.amber.has(k) || tr.lit.blue.has(k))) flowersLit += 1;
  }));
  return { lanterns, litLanterns, flowersLit };
}

export function isSolved(b: Board): boolean {
  const g = goal(b);
  return g.lanterns > 0 && g.litLanterns === g.lanterns && g.flowersLit === 0;
}

/** Turns the mirror at (x, y). Returns the same board when it is not turnable. */
export function turn(b: Board, x: number, y: number): Board {
  const t = b.tiles[y]?.[x];
  if (t !== "m" && t !== "n") return b;
  const tiles = b.tiles.map((r) => r.slice());
  tiles[y][x] = t === "m" ? "n" : "m";
  return { ...b, tiles };
}

/** Sets turnable mirrors from a bitmask (bit i = mirror i is "\"). */
export function withMask(b: Board, mask: number): Board {
  const tiles = b.tiles.map((r) => r.slice());
  b.mirrors.forEach(([x, y], i) => { tiles[y][x] = mask & (1 << i) ? "n" : "m"; });
  return { ...b, tiles };
}

export function maskOf(b: Board): number {
  return b.mirrors.reduce((m, [x, y], i) => (b.tiles[y][x] === "n" ? m | (1 << i) : m), 0);
}

function popcount(n: number): number {
  let c = 0;
  for (let v = n; v; v &= v - 1) c += 1;
  return c;
}

/** Tries every mirror setting. Returns the solving masks and the fewest taps from the board. */
export function analyse(b: Board): { solutions: number[]; minTaps: number } {
  const solutions: number[] = [];
  const total = 1 << b.mirrors.length;
  for (let m = 0; m < total; m++) if (isSolved(withMask(b, m))) solutions.push(m);
  const cur = maskOf(b);
  const minTaps = solutions.length ? Math.min(...solutions.map((s) => popcount(s ^ cur))) : -1;
  return { solutions, minTaps };
}

export function starsFor(taps: number, par: number): number {
  if (taps <= par) return 3;
  if (taps <= par + 2) return 2;
  return 1;
}

